rows={t['id']:t for t in a['performance_and_cost_table']}
assert len(rows)==45 and set(rows)==set(c['allowed_observation_ids'])==set(a['evidence_refs'])
for t in c['trajectory_index']:
 row=rows[t['id']]
 for k in ['id','parent','role','status','wall_seconds']:assert row[k]==t[k],(t['id'],k)
 assert row['validation_auc']==t['auc']
for t in c['history']:
 row=rows[t['id']]
 for k in ['source_sha256','config','parameters','embedding_parameters','dense_parameters','train_seconds','peak_gpu_bytes','error']:assert row[k]==t[k],(t['id'],k)
 for k in ['auc','logloss','samples']:assert row['validation_'+k]==t['validation'][k]
assert a['decision']['incumbent']==c['incumbent']==max(rows,key=lambda x:rows[x]['validation_auc'])
assert a['decision']['best_observed_logloss_model']==min(rows,key=lambda x:rows[x]['validation_logloss'])
f=a['role_routing_factorial'];cs=f['cells']
for m in ['auc','logloss']:
 vals=[t[m] for t in cs]
 assert math.isclose(f['interaction'][m], vals[3]-vals[1]-vals[2]+vals[0],abs_tol=1e-15)
 for t in cs:assert t[m]==rows[t['trial_id']]['validation_'+m]
for con in a['paired_contrasts']:
 for m in ['auc','logloss']:
  delta=rows[con['treatment']]['validation_'+m]-rows[con['control']]['validation_'+m]
  assert math.isclose(con['delta'][m],delta,abs_tol=1e-15)
assert len(a['slice_analysis']['table'])==23
slices={s['slice']:s for s in a['slice_analysis']['table']}
for s in slices.values():
 assert s['count_consistency'] and s['samples']==s['positives']+s['negatives']
 for k in ['auc','logloss']:
  v=[t[k] for t in s['cells']]
  assert math.isclose(s[k+'_interaction'],v[3]-v[1]-v[2]+v[0],abs_tol=1e-15)
for names in [['empty_history','history_1_16','history_17_64','history_gt64'],['hour_0_6','hour_6_12','hour_12_18','hour_18_24']]:
 assert sum(slices[n]['samples'] for n in names)==3234051
 assert sum(slices[n]['positives'] for n in names)==159437
 assert sum(slices[n]['negatives'] for n in names)==3074614
for b in a['reproducibility_bridges']:
 assert b['auc_exact'] and b['logloss_exact']
 for m in ['auc','logloss']:assert rows[b['replay']]['validation_'+m]==rows[b['ancestor']]['validation_'+m]
def check_refs(x):
 if isinstance(x,dict):
  if 'evidence_refs' in x:assert set(x['evidence_refs'])<=set(rows),x['evidence_refs']
  for v in x.values():check_refs(v)
 elif isinstance(x,list):
  for v in x:check_refs(v)
 elif isinstance(x,float):assert math.isfinite(x)
check_refs(a)
cost=a['next_action']['cost'];cap=p['trial_cap_seconds'];unit=p['estimated_unit_seconds']
assert math.isclose(cost['remaining_after_first_block_caps_and_reserves'],cost['remaining_seconds_at_runtime_snapshot']-24*cap-2*unit,abs_tol=1e-9)
assert math.isclose(cost['remaining_after_both_blocks_caps_and_reserves'],cost['remaining_seconds_at_runtime_snapshot']-30*cap-2*unit,abs_tol=1e-9)
assert set(a['next_action']['comparison_suite'])<=set(rows)
print(json.dumps({'artifact':str(path),'bytes':path.stat().st_size,'trials_checked':len(rows),'slice_rows_checked':len(slices),'required_fields':required,'auc_interaction':f['interaction']['auc'],'logloss_interaction':f['interaction']['logloss'],'status':'passed'}))
PY"

